---@return nothing
function s__StackTemplate_deallocate(this)
	if this == nil then
		return 
	elseif (si__StackTemplate_V[this] ~= -1) then
		return 
	end
	si__StackTemplate_V[this] = si__StackTemplate_F
	si__StackTemplate_F = this
end
