	local u = GetFilterUnit()
	if IsPlayerAlly(GetOwningPlayer(u), CheckPlayer) and not (IsUnitIdType(GetUnitTypeId(u), UNIT_TYPE_MECHANICAL)) then
		u = nil
		return true
