		AiData[i][FourCC('h05Y')] = 0
		AiData[i][FourCC('h05V')] = 0
		AiData[i][FourCC('h061')] = 0
		AiData[i][FourCC('h068')] = 0
		AiData[i][FourCC('h05W')] = 0
		AiData[i][FourCC('h062')] = 0
