function SetPortalGroup()
	
	local i = 0
	
	while true do
		if i >= 24 then break end
		AiUnitsToPort[i] = CreateGroup()
		AiCapitalGuard[i] = CreateGroup()
		AiCapitalBuildigs[i] = CreateGroup()
