---@return nothing
function TType()
	if GetUnitTypeId(GetEnumUnit()) == udg_LocalInteger5 then
		GroupAddUnit(udg_LocalOtrad, GetEnumUnit())
	end
end
---@param p player
---@param before integer
---@param after integer
---@return nothing
function BuildT(p, before, after)
	local u = nil
	
	GroupClear(udg_LocalOtrad)
	GroupEnumUnitsOfPlayer(gGroup, p, nil)
	udg_LocalInteger5 = before
	ForGroup(gGroup, TType)
	
	
	gGroup = udg_LocalOtrad
	u = GroupPickRandomUnit2(gGroup)
	if u ~= nil then
		IssueImmediateOrderById(u, after)
		local pi = GetPlayerId(p)
		NumberRem(pi, before)
		NumberAdd(pi, after)
	end
	
	-- Зачистка
	udg_LocalOtrad = CreateGroup()
	
	u = nil
end
-- ***************************************************************************
-- *  TryBuy
---@param p player
---@param ePoints integer
---@return nothing
function TryBuy(p, ePoints)
	
	local u
	local itemId
	local itemGoldCost = 1000
	GroupEnumUnitsOfPlayer(gGroup, p, LiveHero)
	u = GroupPickRandomUnit2(gGroup)
	if u ~= nil then
		local invSize = UnitInventorySize(u)
		if invSize <= 0 then invSize = 6 end

		-- Don't destroy items the hero already owns. If the inventory is
		-- genuinely full we just skip the purchase this tick — the hero will
		-- have another chance when a slot opens naturally.
		if UnitInventoryCount(u) >= invSize then
			u = nil
			return
		end

		gInt = GetRandomInt(1, 6)
		if ePoints < 35 then
			if gInt == 1 then
				itemId = FourCC('I02S')
			elseif gInt == 2 then
				itemId = FourCC('I030')
			elseif gInt == 3 then
				itemId = FourCC('I02Z')
			elseif gInt == 4 then
				itemId = FourCC('I02Y')
			elseif gInt == 5 then
				itemId = FourCC('I02T')
			elseif gInt == 6 then
				itemId = FourCC('I02X')
			end
		elseif ePoints < 150 then
			
			if gInt == 1 then
				itemId = FourCC('I010')
			elseif gInt == 2 then
				itemId = FourCC('I01A')
			elseif gInt == 3 then
				itemId = FourCC('I02Z')
			elseif gInt == 4 then
				itemId = FourCC('I01P')
			elseif gInt == 5 then
				itemId = FourCC('I002')
			elseif gInt == 6 then
				itemId = FourCC('I003')
			end
		else
			
			if gInt == 1 then
				itemId = FourCC('I00W')
			elseif gInt == 2 then
				itemId = FourCC('I030')
			elseif gInt == 3 then
				itemId = FourCC('I011')
			elseif gInt == 4 then
				itemId = FourCC('I00F')
			elseif gInt == 5 then
				itemId = FourCC('I017')
			elseif gInt == 6 then
				itemId = FourCC('I01C')
			end
		end
		
		
		if itemId ~= nil and GetInventoryIndexOfItemTypeBJ(u, itemId) == 0 then
			if GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) >= itemGoldCost then
				local it = UnitAddItemById(u, itemId)
				if it ~= nil and UnitHasItem(u, it) then
					SetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD, GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) - itemGoldCost)
				elseif it ~= nil then
					RemoveItem(it)
				end
			end
		end

	end

	u = nil
end
