			SelectHeroSkill(u, FourCC('A07V'))
		elseif gInt == 1 then
			SelectHeroSkill(u, FourCC('A07U'))
		elseif gInt == 2 then
			SelectHeroSkill(u, FourCC('A0LQ'))
		else
			SelectHeroSkill(u, FourCC('AEar'))
		end
		
		
		
		-- Герой Паладин
	elseif GetUnitTypeId(u) == FourCC('H045') then
