			SelectHeroSkill(u, FourCC('A09J'))
		elseif gInt == 1 then
			SelectHeroSkill(u, FourCC('A09F'))
		elseif gInt == 2 then
			SelectHeroSkill(u, FourCC('A09G'))
		else
			SelectHeroSkill(u, FourCC('A09I'))
		end
		
		
		
		-- Герой Паладин
	elseif GetUnitTypeId(u) == FourCC('H03H') then
