				AddUnit(FourCC('h060'), 1)	--  
				AddUnit(FourCC('h06Q'), 3)	--  
				AddUnit(FourCC('h06L'), 3)	--  
				AddUnit(FourCC('h06N'), 3)	--  
				AddUnit(FourCC('h078'), 3)	--  
				AddUnit(FourCC('h06M'), 3)	--  
			end
			
		end
		
		--  Штаб
	elseif id == FourCC('h070') then
