	framehandlefps = BlzGetFrameByName("ResourceBarFrame", 0)
	BlzFrameSetVisible(fps, true)
	BlzFrameClearAllPoints(fps)
	BlzFrameSetAbsPoint(fps, FRAMEPOINT_CENTER, 0.95, 0.62)
end
