-- ***************************************************************************
-- *  ClearPlayer
---@return nothing
function KillAll()
	local u = GetEnumUnit()
	local id = GetUnitTypeId(u)
	local p = GetOwningPlayer(u)
	if IsUnitInGroup(u, udg_ZahvatBuildings) or GetUnitAbilityLevel(u, FourCC('A1HJ')) > 0 then
		SetUnitOwner(u, Player(25), true)
		SetUnitLifePercentBJ(u, 100)
	elseif IsUnitInGroup(u, udg_StolicaGroups) then
		RemoveUnit(u)
	else
		-- ?????? ?????? ?????
		if id == FourCC('h0KS') then
			UnitRemoveAbility(u, FourCC('A18O'))
		end
		if IsUnitType(u, UNIT_TYPE_HERO) then
			SetPlayerTechMaxAllowed(p, id, GetPlayerTechMaxAllowed(p, id) + 1)
		end
		RemoveUnit(u)
	end
	
	u = nil
	p = nil
end
---@param p player
---@return nothing
function ClearPlayer(p)
	local pi = GetPlayerId(p)
	local g = CreateGroup()
	
	GroupEnumUnitsOfPlayer(g, p, nil)
	ForGroup(g, KillAll)
	GroupClear(g)
	SetPlayerStateBJ(Player(pi), PLAYER_STATE_RESOURCE_GOLD, 0)
	SetPlayerStateBJ(Player(pi), PLAYER_STATE_RESOURCE_LUMBER, 0)
	
	SetPlayerAbilityAvailable(Player(pi), FourCC('A0IQ'), true)
	ClearEc(pi)
	turnOffAi(pi)
	UpdateGraf(pi)
	playerCapital[pi] = nil
	ArmyExp[pi] = 0.0
	
	-- Vassal cleanup when in Feoda mode
	if IsTriggerEnabled(gg_trg_FeodalDead) and CountPlayersInForceBJ(Vassals[pi]) > 0 then
		local inheritedSenior = Senior[pi]
		if FeodalVassalMode == 1 then
			-- Mode 1: transfer vassals to the senior's senior
			if inheritedSenior ~= nil then
				local inheritedPi = GetPlayerId(inheritedSenior)
				ForForce(Vassals[pi], function()
					local v = GetEnumPlayer()
					local vi = GetPlayerId(v)
					ClearOldAllies(v)
					Senior[vi] = inheritedSenior
					ForceAddPlayer(Vassals[inheritedPi], v)
					NewAlly(v)
				end)
				DisplayTextToForce(udg_AllPlayers, GetPlayerName(inheritedSenior) .. " inherited vassals of dead player " .. GetPlayerName(p))
			else
				-- No senior — free all vassals
				ForForce(Vassals[pi], Freedom)
			end
		else
			-- Mode 2: all vassals are eliminated
			ForForce(Vassals[pi], function()
				local v = GetEnumPlayer()
				ClearPlayer(v)
			end)
			DisplayTextToForce(udg_AllPlayers, "Vassals of dead player " .. GetPlayerName(p) .. " are eliminated!")
		end
		-- Remove ourselves from our senior's vassal force
		if inheritedSenior ~= nil then
			ForceRemovePlayer(Vassals[GetPlayerId(inheritedSenior)], Player(pi))
		end
	end
	ForceClear(Vassals[pi])
	Senior[pi] = nil
	
	DestroyGroup(g)
	g = nil
end
-- ***************************************************************************
-- *  TimedUpdate
---@param u unit
---@param p player
---@return nothing
function TimedUpdate(u, p)
    local currentLevel = 1
    local pi = GetPlayerId(p)
    
    UnitAddAbility(u, FourCC('A10G'))
    BlzStartUnitAbilityCooldown(u, FourCC('A10G'), 300)
    
    local function tick(tt)
        local levels = 4
        if GetUnitAbilityLevel(GetTriggerUnit(), FourCC('A1N9')) > 0 then
            levels = levels - 2
        end
        
        if GetOwningPlayer(u) == p and UnitAlive(u) and currentLevel <= levels then
            BlzStartUnitAbilityCooldown(u, FourCC('A10G'), 300)
            
            if GetUnitAbilityLevel(u, FourCC('A0AY')) == 0 then
                UnitAddAbility(u, FourCC('A0AY'))
                income[pi] = income[pi] + 100
            elseif GetUnitAbilityLevel(u, FourCC('A0AY')) < levels then
                income[pi] = income[pi] + 100
                IncUnitAbilityLevel(u, FourCC('A0AY'))
            else
                income[pi] = income[pi] + 100
                UnitRemoveAbility(u, FourCC('A0AZ'))
            end
            
            if GetUnitAbilityLevel(u, FourCC('A0B5')) == 0 then
                UnitAddAbility(u, FourCC('A0B5'))
                incomeW[pi] = incomeW[pi] + 50.00
            elseif GetUnitAbilityLevel(u, FourCC('A0B5')) < levels then
                IncUnitAbilityLevel(u, FourCC('A0B5'))
                incomeW[pi] = incomeW[pi] + 50.00
            else
                UnitRemoveAbility(u, FourCC('A0B1'))
            end
            
            if GetUnitAbilityLevel(u, FourCC('A0AY')) + GetUnitAbilityLevel(u, FourCC('A0B5')) >= levels * 2 then
                BlzUnitHideAbility(u, FourCC('A10G'), true)
                BlzUnitDisableAbility(u, FourCC('A10G'), true, true)
            end
            
            UpdateGraf(pi)
            currentLevel = currentLevel + 1
            TimerStart(tt, 300, false, function() tick(tt) end)
        else
            DestroyTimer(tt)
        end
    end
    
    local t = CreateTimer()
    TimerStart(t, 300, false, function() tick(t) end)
end
