function RandomAiPlace()
	local i = 0
	local c = 0
	local b = {}
	
	i = 0
	while true do
		if i >= 15 then break end
		
		if PointForAi[i] ~= nil then
			b[c] = PointForAi[i]
			PointForAi[i] = nil
			c = c + 1
		end
		i = i + 1
	end
	--  ??????? ?????? ??????? ?
	
	i = GetRandomInt(0, c - 1)
	udg_LocalPoint = b[i]
	i = 0
	while true do
		if i >= 15 then break end
		b[i] = nil
		
		i = i + 1
	end
	
	
end
