-- ***************************************************************************
-- *  GoToWater
---@param pi integer
---@param u unit
---@param x real
---@param y real
---@return boolean
function GoToWaterPoint(pi, u, x, y)
	
	local numPorts = AiData[pi][StringHash("NumberPorts")] or 0
	if numPorts < 8 and Random(3 - numPorts, 10) then
		if RectContainsCoords(gg_rct_EastenKingdoms, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", 30150, -3454)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", 25504, -16284)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", 19258, 5665)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", 10979, 10501)
			end
		elseif RectContainsCoords(gg_rct_Kalim, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", -28610, 16300)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", -15796, -10105)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", -12405, 96678)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", -27443, 11058)
			end
		elseif RectContainsCoords(gg_rct_Nord, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", -4711, 20912)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", 8753, 22230)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", 1273, 20088)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", -15652, 21381)
			end
		elseif RectContainsCoords(gg_rct_BrokenIsles, x, y) then
			gInt = GetRandomInt(1, 2)
			if gInt == 1 then
				IssuePointOrder(u, "move", 2500, 12654)
			else
				IssuePointOrder(u, "move", 4121, 621)
			end
		elseif RectContainsCoords(gg_rct_Pandaria, x, y) then
			gInt = GetRandomInt(1, 2)
			if gInt == 1 then
				IssuePointOrder(u, "move", -9460, -12451)
			else
				IssuePointOrder(u, "move", -3941, -22869)
			end
		end
		
		return true
	end
	return false
end
-- ***************************************************************************
-- *  TryToBuild
---@return nothing
function TryBuild()
    gUnit = TryBuild_u
    if gUnit == nil then return end
    gPi = GetPlayerId(GetOwningPlayer(gUnit))
    gX = GetUnitX(gUnit)
    gY = GetUnitY(gUnit)

    GroupAddUnit(udg_Ai_buildersT[gPi], gUnit)
    GroupRemoveUnit(udg_Ai_builders[gPi], gUnit)
    GroupRemoveUnit(udg_Ai_harvest[gPi], gUnit)

    gInt = AiData[gPi][StringHash("NumberPorts")] or 0
    if gInt < 3 and AiRaceUsesWaterPoint(gPi) and Random(1, 15) and GoToWaterPoint(gPi, gUnit, gX, gY) then
        return
    end

    -- NB: the old "4% chance: walk 7x build-radius away with a bare move order" was
    -- removed — it sent workers far from base with no follow-up build, so they just
    -- wandered off and sat idle (observed: groups of lost workers, drained build/
    -- harvest force). Map expansion comes from the army capturing neutral cities.
    gInt = AiDispatchChooseBuild(gPi)
    if AiSmartBuild then
        local bx, by = AiFindBuildSpot(gPi, gUnit)
        if bx ~= nil then
            BrainLogEvery(gPi, "build", 6, "smart spot x=" .. tostring(R2I(bx)) .. " y=" .. tostring(R2I(by)) .. " build=" .. tostring(gInt), "BRAINBLD")
            IssueBuildOrderById(gUnit, gInt, bx, by)
            return
        end
    end
    gX = gX + AiBuildingRadius * Cos(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
    gY = gY + AiBuildingRadius * Sin(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
    IssueBuildOrderById(gUnit, gInt, gX, gY)
end
-- ***************************************************************************
-- *  AiUnitJoins
---@param u unit
---@param pi integer
---@return nothing
function aiUnitJoins(u, pi)
    local id = GetUnitTypeId(u)

    GroupAddUnit(udg_Ai_units[pi], u)
    NumberAdd(pi, id)

    AiDispatchJoin(id, pi, u)

    -- Workers: join builder pool, call TryBuild immediately.
    -- PlayerBuilders will retry from buildersT pool on timer.
    if IsUnitType(u, UNIT_TYPE_PEON) then
        GroupAddUnit(udg_Ai_builders[pi], u)
        TryBuild_u = u
        TryBuild()
    end
end
