--  Легендарки: здание -> раса AI (ключ из AiRaces), которой принадлежит здание
--  Если раса не указана (nil) — легендарка доступна любой расе
-- ===========================================================================
LegendaryBuildingToRace = {
	[FourCC('h07Z')] = "Stromgard",
	[FourCC('h081')] = "Stromgard",
	[FourCC('h087')] = "Stromgard",
	[FourCC('h07Y')] = "Scarlet",
	[FourCC('h00N')] = "Scarlet",
	[FourCC('h00W')] = "BloodElves",
	[FourCC('h07F')] = "BloodElves",
	[FourCC('h07T')] = "BloodElves",
	[FourCC('h08F')] = "Goblins",
	[FourCC('h0BL')] = "Goblins",
	[FourCC('h0O3')] = "Goblins",
	[FourCC('h07V')] = "Forsaken",
	[FourCC('h08L')] = "Silitids",
	[FourCC('h00I')] = "Alliance",
	[FourCC('h0N0')] = "JungleTrolls",
	[FourCC('h07U')] = "ForestTrolls",
	[FourCC('h09K')] = "IceTrolls",
	[FourCC('h072')] = "Undead",
	[FourCC('h09G')] = "Undead",
	[FourCC('h080')] = "Undead",
	[FourCC('h0F3')] = "Undead",
	[FourCC('h0NB')] = "Dalaran",
	[FourCC('h0DR')] = "Demons",
	[FourCC('h05F')] = "HordeW2",
	[FourCC('h09Q')] = "Vrykul",
}

function GiveBotLegendaryHeroes(u2, p, pi)
	if not udg_AiControl[pi] then
		return
	end
	local bid = GetUnitTypeId(u2)
	local heroes = LegendaryBuildingToHero[bid]
	if heroes == nil then
		return
	end
	local requiredRace = LegendaryBuildingToRace[bid]
	if requiredRace ~= nil then
		local botRace = AiRace[pi]
		if botRace ~= requiredRace then
			return
		end
	end
	local x = GetUnitX(u2)
	local y = GetUnitY(u2)
	for _, hid in ipairs(heroes) do
		local existing = GetUnitsOfPlayerAndTypeId(p, hid)
		if BlzGroupGetSize(existing) == 0 then
			SetPlayerTechMaxAllowed(p, hid, 1)
			local hero = CreateUnit(p, hid, x, y, bj_UNIT_FACING)
			if hero ~= nil then
				aiUnitJoins(hero, pi)
			end
		end
	end
end

-- ===========================================================================
--  Trigger: DeadSituastion
-- ===========================================================================
---@return boolean
function Trig_DeadSituastion_Conditions()
	return IsUnitInGroup(GetTriggerUnit(), udg_ZahvatBuildings)
end
---@return nothing
function Trig_DeadSituastion_Actions()
	local u = GetTriggerUnit()
	local u2
	local id = GetUnitTypeId(u)
	local u3 = GetKillingUnit()
	local p = GetOwningPlayer(u3)
	if p == nil then
		p = Player(PLAYER_NEUTRAL_AGGRESSIVE)
	end
	local pi0 = GetPlayerId(GetOwningPlayer(u))
	local pi = GetPlayerId(p)
	local i
	
	
	-- ??? ?????? ?????????
	
	CityPlayerCount[pi0] = (CityPlayerCount[pi0] or 0) - 1
	CityPlayerCount[pi] = (CityPlayerCount[pi] or 0) + 1
	PercentGraph(pi0)
	PercentGraph(pi)
	if udg_GameMode == 3 or udg_GameMode == 5 then
		CheckCity(p)
	end
	
	-- ????? ???????? ?????????? ????? ?????.
	u2 = CreateUnit(p, GetUnitTypeId(u), GetUnitX(u), GetUnitY(u), GetUnitFacing(u))
	GroupAddUnit(udg_ZahvatBuildings, u2)
	BlzSetUnitArmor(u2, 3)
	SetUnitState(u2, UNIT_STATE_LIFE, 5000)
	GroupAddUnit(udg_BuildedSctructure[1], u2)
	
	-- ??????? ??? ????? ??????
	if GetUnitAbilityLevel(u, FourCC('A1MS')) == 0 then
		UnitAddAbility(u2, FourCC('A0VJ'))
	end
	
	UnitRemoveAbility(u2, FourCC('A0B2'))
	UnitRemoveAbility(u2, FourCC('A0B0'))
	UnitRemoveAbility(u2, FourCC('A0MK'))
	
	
	
	
	
	
	
	
	
	-- ???????? ?? ?????????? ?????
	if IsUnitInGroup(u, udg_CityNearWater) then
		GroupRemoveUnit(udg_CityNearWater, u)
		GroupAddUnit(udg_CityNearWater, u2)
	end
	
	-- ???????? ?? ??
	if IsUnitInGroup(u, PortalBuildingAi) then
		GroupAddUnit(PortalBuildingAi, u2)
		
		if udg_AiControl[pi] then
			UnitAddAbility(u2, FourCC('A0Y4'))
			GroupAddUnit(AiUnitsToPort[pi], u2)
			if Random(1, 3) then
				PortTo(u2)
			end
		end
	elseif udg_AiControl[pi] then
		aiKilledCity(u3)
	end
	
	
	GiveBotLegendaryHeroes(u2, p, pi)
	
	u = nil
	u3 = nil
	
	-- ??????????
	if GetUnitAbilityLevel(u2, FourCC('A1MS')) == 0 then
		TimedUpdate(u2, p)
	end
	
	u2 = nil
	
	
end
