function CapitalOfEnemy()
    return IsUnitInGroup(GetFilterUnit(), udg_StolicaGroups) and IsPlayerEnemy(GetOwningPlayer(GetFilterUnit()), udg_LocalPlayer)
end
function Trig_NoTpNearCapital_Actions()
    local g= CreateGroup()
    local u= GetTriggerUnit()
   
    udg_LocalPlayer=GetOwningPlayer(u)
    GroupEnumUnitsInRange(g, GetUnitX(u), GetUnitY(u), 1350.00, nil)
    local found = false
    local sz = BlzGroupGetSize(g)
    for i = 0, sz - 1 do
        local eu = BlzGroupUnitAt(g, i)
        if eu ~= nil and IsUnitInGroup(eu, udg_StolicaGroups) and IsPlayerEnemy(GetOwningPlayer(eu), udg_LocalPlayer) then
            found = true
            break
        end
    end
    if found then
        IssueImmediateOrder(u, "stop")
        DisplayTextToPlayer(GetOwningPlayer(u), 0, 0, " - ")
    end
    
    DestroyGroup(g)
    g=nil
    u=nil
    
end
