--===========================================================================
-- Trigger: F2 2
--===========================================================================
function Trig_F2_2_Actions()
    local pi= GetPlayerId(GetOwningPlayer(GetTriggerUnit()))
    local g= CreateGroup()
    local g0= CreateGroup()
    local u
    local i= 0
    local loc= GetSpellTargetLoc()
    
    --set g = udg_F_Group[pi+1]
    GroupAddGroup(udg_F_Group[pi + 1], g)
    local fgSize = BlzGroupGetSize(g)
    local fgIdx = 0
    while fgIdx < fgSize do
        fgIdx = fgIdx + 1
        u = BlzGroupUnitAt(g, fgIdx)
        if u == nil then
            GroupPointOrderLoc(g0, "attack", loc)
            if true then break end
        end

        if i == 12 then
            GroupPointOrderLoc(g0, "attack", loc)
            i=0
            GroupClear(g0)

        end
        i=i + 1
        GroupAddUnit(g0, u)
        u=nil
    end
    DestroyGroup(g)
    DestroyGroup(g0)
    g=nil
    g0=nil
    RemoveLocation(loc)
    loc=nil
end
