    gg_trg_Banshe=CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(gg_trg_Banshe, EVENT_PLAYER_UNIT_SPELL_EFFECT)
    TriggerAddAction(gg_trg_Banshe, function()
