    TriggerRegisterAnyUnitEventBJ(gg_trg_K1T1, EVENT_PLAYER_UNIT_TRAIN_FINISH)
    TriggerAddCondition(gg_trg_K1T1, Condition(Trig_K1T1_Conditions))
    TriggerAddAction(gg_trg_K1T1, Trig_K1T1_Actions)
