-- Trigger: SpellBook
--===========================================================================
function Trig_SpellBook_Actions()
    local u1
    local g= CreateGroup()
    local i= 0
    
    udg_Boolexpr = HaveSpell
    GroupEnumUnitsSelected(g, GetOwningPlayer(GetTriggerUnit()), udg_Boolexpr)
    while true do
            u1=FirstOfGroup(g)
            if u1 == nil then break end
            IssueImmediateOrder(u1, "spellbook")
            GroupRemoveUnit(g, u1)
    end
    
    
    
    
    DestroyGroup(g)
    u1=nil
    g=nil
end
