    TriggerRegisterAnyUnitEventBJ(gg_trg_SpellBook, EVENT_PLAYER_UNIT_SPELL_FINISH)
    TriggerAddAction(gg_trg_SpellBook, function()
        if GetSpellAbilityId() ~= FourCC('A1AV') then return end
        Trig_SpellBook_Actions()
    end)
end
