    local id= GetUnitTypeId(GetTriggerUnit())
    return id == FourCC('etoa') or id == FourCC('etol') or id == FourCC('etoe') or id == FourCC('eaoe') or id == FourCC('eaom') or id == FourCC('eaow') or id == FourCC('etrp')
